// factsheet.service.ts
import { Injectable } from '@angular/core';
import { HttpClient, HttpParams } from '@angular/common/http';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';

// If you have real response types, replace `any` below with proper interfaces.
type ApiResponse<T = any> = T & { msg?: number };

@Injectable({ providedIn: 'root' })
export class FactsheetService {
  private readonly cloudUrl = `${environment.cloudUrl2}${environment.realtimeserive}`;
  private readonly baseUrl = `${this.cloudUrl}/factsheet`;

  constructor(private http: HttpClient) { }

  private buildParams(nFSid: string): HttpParams {
    return new HttpParams().set('nFSid', nFSid); // do NOT include nMasterid
  }

  /** GET /factsheet/detail?nFSid=... */
  async getFactDetail<T = any>(nFSid: string): Promise<T | null> {
    const params = this.buildParams(nFSid);
    try {
      const res = await firstValueFrom(
        this.http.get<ApiResponse<T>>(`${this.baseUrl}/detail`, { params })
      );
      if (res?.msg === -1) return null;
      return res as T;
    } catch {
      return null;
    }
  }




  /** GET /factsheet/issues?nFSid=... */
  async getFactShared<T = any>(nFSid: string): Promise<T | null> {
    const params = this.buildParams(nFSid);
    try {
      const res = await firstValueFrom(
        this.http.get<ApiResponse<T>>(`${this.baseUrl}/shared`, { params })
      );
      if (res?.msg === -1) return null;
      return res as T;
    } catch {
      return null;
    }
  }
  /** GET /factsheet/issues?nFSid=... */
  async getFactIssues<T = any>(nFSid: string): Promise<T | null> {
    const params = this.buildParams(nFSid);
    try {
      const res = await firstValueFrom(
        this.http.get<ApiResponse<T>>(`${this.baseUrl}/issues`, { params })
      );
      if (res?.msg === -1) return null;
      return res as T;
    } catch {
      return null;
    }
  }

  /** GET /factsheet/contacts?nFSid=... */
  async getFactContacts<T = any>(nFSid: string): Promise<T | null> {
    const params = this.buildParams(nFSid);
    try {
      const res = await firstValueFrom(
        this.http.get<ApiResponse<T>>(`${this.baseUrl}/contacts`, { params })
      );
      if (res?.msg === -1) return null;
      return res as T;
    } catch {
      return null;
    }
  }

  /** GET /factsheet/tasks?nFSid=... */
  async getFactTasks<T = any>(nFSid: string): Promise<T | null> {
    const params = this.buildParams(nFSid);
    try {
      const res = await firstValueFrom(
        this.http.get<ApiResponse<T>>(`${this.baseUrl}/tasks`, { params })
      );
      if (res?.msg === -1) return null;
      return res as T;
    } catch {
      return null;
    }
  }


  /** GET /factsheet/tasks?nFSid=... */
  async getFactLinks<T = any>(nFSid: string): Promise<T | null> {
    const params = this.buildParams(nFSid);
    try {
      const res = await firstValueFrom(
        this.http.get<ApiResponse<T>>(`${this.baseUrl}/links`, { params })
      );
      if (res?.msg === -1) return null;
      return res as T;
    } catch {
      return null;
    }
  }


  async saveFact(mdl): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${this.baseUrl}/save`, mdl)
      );
      return res;
    } catch (err) {
      return { msg: -1, error: err, value: '' };
    }
  }


  async unshare(nFSid): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${this.baseUrl}/unshare`, { nFSid })
      );
      return res;
    } catch (err) {
      return { msg: -1, error: err, value: '' };
    }
  }

  async delete(nFSid): Promise<any> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<any>(`${this.baseUrl}/delete`, { nFSid })
      );
      return res;
    } catch (err) {
      return { msg: -1, error: err, value: '' };
    }
  }

}
